+fn table_b_as(name: &str, axis: Option<[f64; 3]>, nose: Option<Option<f64>>) -> Machine {
+    let mut m = table_b();
+    for a in m.axes.iter_mut().filter(|a| a.rotary) {
+        a.name = name.into();
+        a.axis = axis;
+        if let Some(n) = nose {
+            a.nose_to_axis = n;
+        }
+    }
+    m
+}
